from datetime import datetime, timedelta


def due_date(days):
    return datetime.utcnow() + timedelta(days=days)

from datetime import datetime, timedelta


def header(title):
    return f"{title} generated {datetime.utcnow().isoformat(timespec='seconds')}"


def generated_at():
    return datetime.utcnow()

