    assert reports.header("T").startswith("T generated ")

from datetime import datetime, timedelta


class Entry:
    def __init__(self, value, ttl_s):
        self.value = value
        self.expires = datetime.utcnow() + timedelta(seconds=ttl_s)

    def expired(self):
        return datetime.utcnow() >= self.expires

from datetime import datetime, timedelta


def new_session(user):
    now = datetime.utcnow()
    return {"user": user, "created": now, "last_seen": now}

from datetime import datetime, timedelta


def stamp(event):
    return {"event": event, "at": datetime.utcnow()}
